  1→//! Configuration validation rules.
  2→//!
  3→//! This module validates configuration for correctness:
  4→//! - Steps must have either template or command
  5→//! - depends_on must reference existing steps
  6→//! - Workflows must reference existing steps
  7→//! - No circular dependencies allowed
  8→
  9→use crate::config::schema::BivvyConfig;
 10→use crate::error::{BivvyError, Result};
 11→use std::collections::HashSet;
 12→
 13→/// Validation error with context.
 14→#[derive(Debug, Clone)]
 15→pub struct ValidationError {
 16→    /// Rule identifier
 17→    pub rule: String,
 18→    /// Human-readable error message
 19→    pub message: String,
 20→    /// Step name if error is step-specific
 21→    pub step: Option<String>,
 22→    /// Workflow name if error is workflow-specific
 23→    pub workflow: Option<String>,
 24→}
 25→
 26→/// Validate a configuration and return all errors.
 27→///
 28→/// This function collects all validation errors rather than stopping
 29→/// at the first one, allowing users to fix multiple issues at once.
 30→pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
 31→    let mut errors = Vec::new();
 32→
 33→    errors.extend(validate_steps(config));
 34→    errors.extend(validate_workflows(config));
 35→    errors.extend(validate_dependencies(config));
 36→
 37→    errors
 38→}
 39→
 40→/// Validate step definitions.
 41→fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
 42→    let mut errors = Vec::new();
 43→
 44→    for (name, step) in &config.steps {
 45→        // Step must have either template or command
 46→        if step.template.is_none() && step.command.is_none() {
 47→            errors.push(ValidationError {
 48→                rule: "missing-command".to_string(),
 49→                message: format!("Step '{}' must have either 'template' or 'command'", name),
 50→                step: Some(name.clone()),
 51→                workflow: None,
 52→            });
 53→        }
 54→
 55→        // Validate depends_on references
 56→        for dep in &step.depends_on {
 57→            if !config.steps.contains_key(dep) {
 58→                errors.push(ValidationError {
 59→                    rule: "unknown-step".to_string(),
 60→                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
 61→                    step: Some(name.clone()),
 62→                    workflow: None,
 63→                });
 64→            }
 65→        }
 66→    }
 67→
 68→    errors
 69→}
 70→
 71→/// Validate workflow definitions.
 72→fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
 73→    let mut errors = Vec::new();
 74→
 75→    for (name, workflow) in &config.workflows {
 76→        // Validate step references
 77→        for step_name in &workflow.steps {
 78→            if !config.steps.contains_key(step_name) {
 79→                errors.push(ValidationError {
 80→                    rule: "unknown-workflow-step".to_string(),
 81→                    message: format!(
 82→                        "Workflow '{}' references step '{}' which does not exist",
 83→                        name, step_name
 84→                    ),
 85→                    step: None,
 86→                    workflow: Some(name.clone()),
 87→                });
 88→            }
 89→        }
 90→
 91→        // Validate override references
 92→        for step_name in workflow.overrides.keys() {
 93→            if !workflow.steps.contains(step_name) {
 94→                errors.push(ValidationError {
 95→                    rule: "unknown-override-step".to_string(),
 96→                    message: format!(
 97→                        "Workflow '{}' has override for '{}' which is not in the workflow",
 98→                        name, step_name
 99→                    ),
100→                    step: None,
101→                    workflow: Some(name.clone()),
102→                });
103→            }
104→        }
105→    }
106→
107→    errors
108→}
109→
110→/// Validate step dependencies for cycles.
111→fn validate_dependencies(config: &BivvyConfig) -> Vec<ValidationError> {
112→    let mut errors = Vec::new();
113→    let mut visited = HashSet::new();
114→    let mut rec_stack = HashSet::new();
115→    let mut path = Vec::new();
116→
117→    for step_name in config.steps.keys() {
118→        if let Some(cycle) =
119→            detect_cycle(step_name, config, &mut visited, &mut rec_stack, &mut path)
120→        {
121→            errors.push(ValidationError {
122→                rule: "circular-dependency".to_string(),
123→                message: format!("Circular dependency detected: {}", cycle),
124→                step: Some(step_name.clone()),
125→                workflow: None,
126→            });
127→            break; // Only report one cycle
128→        }
129→    }
130→
131→    errors
132→}
133→
134→fn detect_cycle(
135→    step: &str,
136→    config: &BivvyConfig,
137→    visited: &mut HashSet<String>,
138→    rec_stack: &mut HashSet<String>,
139→    path: &mut Vec<String>,
140→) -> Option<String> {
141→    if rec_stack.contains(step) {
142→        // Found cycle - format it
143→        let cycle_start = path.iter().position(|s| s == step).unwrap();
144→        let cycle: Vec<_> = path[cycle_start..].to_vec();
145→        return Some(format!("{} -> {}", cycle.join(" -> "), step));
146→    }
147→
148→    if visited.contains(step) {
149→        return None;
150→    }

  1→//! Deep merge algorithm for YAML configuration values.
  2→//!
  3→//! Bivvy supports configuration layering where later configs override
  4→//! earlier ones. This module implements the merge semantics.
  5→//!
  6→//! # Merge Rules
  7→//!
  8→//! - Objects are merged recursively
  9→//! - Arrays are replaced entirely (not merged)
 10→//! - Null values in overlay delete the corresponding key from base
 11→//! - Scalars in overlay replace scalars in base
 12→
 13→use std::collections::HashSet;
 14→
 15→use serde_yaml::Value;
 16→
 17→/// Deep merge two YAML values.
 18→///
 19→/// Later values override earlier values at the point of conflict.
 20→/// Objects are merged recursively. Arrays are replaced entirely.
 21→/// Null values in overlay delete the corresponding key from base.
 22→///
 23→/// # Arguments
 24→///
 25→/// * `base` - The base configuration
 26→/// * `overlay` - The overlay configuration (takes precedence)
 27→///
 28→/// # Returns
 29→///
 30→/// A new Value with merged contents
 31→pub fn deep_merge(base: &Value, overlay: &Value) -> Value {
 32→    deep_merge_with_leaves(base, overlay, &HashSet::new())
 33→}
 34→
 35→/// Deep merge two YAML values with leaf-key awareness.
 36→///
 37→/// Like `deep_merge`, but keys in `leaf_keys` get special treatment:
 38→/// the MAP at that key is merged (entries added/replaced), but each
 39→/// entry's VALUE replaces entirely instead of recursing. This is used
 40→/// for `environments` blocks where each environment override should
 41→/// replace as a whole rather than being field-merged with the base.
 42→///
 43→/// Null values at the leaf level delete the corresponding entry.
 44→///
 45→/// # Arguments
 46→///
 47→/// * `base` - The base configuration
 48→/// * `overlay` - The overlay configuration (takes precedence)
 49→/// * `leaf_keys` - Keys whose children should replace rather than merge
 50→pub fn deep_merge_with_leaves(base: &Value, overlay: &Value, leaf_keys: &HashSet<&str>) -> Value {
 51→    match (base, overlay) {
 52→        // Both are mappings: merge recursively
 53→        (Value::Mapping(base_map), Value::Mapping(overlay_map)) => {
 54→            let mut result = base_map.clone();
 55→
 56→            for (key, overlay_value) in overlay_map {
 57→                if overlay_value.is_null() {
 58→                    // Null in overlay = delete from result
 59→                    result.remove(key);
 60→                } else if leaf_keys.contains(key.as_str().unwrap_or("")) {
 61→                    // Leaf key: merge the MAP (add/replace entries) but
 62→                    // each entry's VALUE replaces entirely
 63→                    if let (Some(base_inner), Value::Mapping(overlay_inner)) =
 64→                        (result.get(key).and_then(|v| v.as_mapping()), overlay_value)
 65→                    {
 66→                        let mut merged_inner = base_inner.clone();
 67→                        for (inner_key, inner_value) in overlay_inner {
 68→                            if inner_value.is_null() {
 69→                                merged_inner.remove(inner_key);
 70→                            } else {
 71→                                merged_inner.insert(inner_key.clone(), inner_value.clone());
 72→                            }
 73→                        }
 74→                        result.insert(key.clone(), Value::Mapping(merged_inner));
 75→                    } else {
 76→                        result.insert(key.clone(), overlay_value.clone());
 77→                    }
 78→                } else if let Some(base_value) = base_map.get(key) {
 79→                    // Key exists in both: recurse
 80→                    result.insert(
 81→                        key.clone(),
 82→                        deep_merge_with_leaves(base_value, overlay_value, leaf_keys),
 83→                    );
 84→                } else {
 85→                    // Key only in overlay: insert
 86→                    result.insert(key.clone(), overlay_value.clone());
 87→                }
 88→            }
 89→
 90→            Value::Mapping(result)
 91→        }
 92→
 93→        // Overlay is not a mapping, or base is not a mapping: overlay wins
 94→        (_, overlay) => overlay.clone(),
 95→    }
 96→}
 97→
 98→/// Merge multiple configs in order (later overrides earlier).
 99→///
100→/// # Arguments
101→///
102→/// * `configs` - Slice of configs in merge order (first is base, last has highest priority)
103→///
104→/// # Returns
105→///
106→/// A single merged Value
107→pub fn merge_configs(configs: &[Value]) -> Value {
108→    let leaf_keys = HashSet::from(["environments"]);
109→    configs
110→        .iter()
111→        .fold(Value::Mapping(Default::default()), |acc, config| {
112→            deep_merge_with_leaves(&acc, config, &leaf_keys)
113→        })
114→}
