140→/// Known private/internal hostnames that should be blocked for SSRF prevention.
141→const BLOCKED_HOSTS: &[&str] = &["localhost", "127.0.0.1", "0.0.0.0", "[::1]"];
142→
143→/// Known cloud metadata IP addresses.
144→const BLOCKED_IPS: &[&str] = &["169.254.169.254", "100.100.100.200"];
145→
146→/// Extract the host from an HTTP/HTTPS URL.
147→fn extract_host(url: &str) -> Option<String> {
148→    // Strip scheme
149→    let without_scheme = url
150→        .strip_prefix("https://")
151→        .or_else(|| url.strip_prefix("http://"))?;
152→    // Take everything before the first '/' or end
153→    let host_port = without_scheme.split('/').next()?;
154→    // Strip port if present
155→    let host = if host_port.starts_with('[') {
156→        // IPv6: [::1]:8080
157→        host_port.split(']').next().map(|h| format!("{}]", h))
158→    } else {
159→        Some(host_port.split(':').next().unwrap_or(host_port).to_string())
160→    };
161→    host
162→}
163→
164→/// Validate extends configuration.
165→pub fn validate_extends(extends: &[ExtendsConfig]) -> Result<()> {
166→    for ext in extends {
167→        if ext.url.is_empty() {
168→            return Err(anyhow!("Extends URL cannot be empty"));
169→        }
170→        if !ext.url.starts_with("http://") && !ext.url.starts_with("https://") {
171→            return Err(anyhow!("Extends URL must be HTTP/HTTPS: {}", ext.url));
172→        }
173→        // SSRF prevention: block private/internal addresses
174→        if let Some(host) = extract_host(&ext.url) {
175→            let host_lower = host.to_lowercase();
176→            if BLOCKED_HOSTS.iter().any(|&h| host_lower == h) {
177→                return Err(anyhow!(
178→                    "Extends URL must not reference localhost or loopback addresses: {}",
179→                    ext.url
180→                ));
181→            }
182→            if BLOCKED_IPS.iter().any(|&ip| host_lower == ip) {
183→                return Err(anyhow!(
184→                    "Extends URL must not reference internal/metadata IP addresses: {}",
185→                    ext.url
186→                ));
187→            }
188→            // Block 10.x.x.x, 172.16-31.x.x, 192.168.x.x ranges
189→            if let Ok(ip) = host.parse::<std::net::Ipv4Addr>() {
190→                if ip.is_private() || ip.is_loopback() || ip.is_link_local() {
191→                    return Err(anyhow!(
192→                        "Extends URL must not reference private IP addresses: {}",
193→                        ext.url
194→                    ));
195→                }
196→            }
197→        }
198→    }
199→    Ok(())
200→}

 1→//! Bivvy CLI entry point.
 2→
 3→use std::process::ExitCode;
 4→
 5→use bivvy::cli::{Cli, CommandDispatcher, Commands};
 6→use bivvy::shell::is_ci;
 7→use bivvy::ui::{create_ui, OutputMode};
 8→use clap::Parser;
 9→use tracing_subscriber::{fmt, prelude::*, EnvFilter};
10→
11→/// Initialize the tracing subscriber for logging.
12→///
13→/// Log level is controlled by:
14→/// 1. `--debug` flag sets level to DEBUG
15→/// 2. `RUST_LOG` environment variable (if set)
16→/// 3. Default is INFO
17→fn init_tracing(debug: bool) {
18→    let filter = if debug {
19→        EnvFilter::new("bivvy=debug")
20→    } else {
21→        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
22→    };
23→
24→    tracing_subscriber::registry()
25→        .with(fmt::layer().with_target(false))
26→        .with(filter)
27→        .init();
28→}
29→
30→fn main() -> ExitCode {
31→    let cli = Cli::parse();
32→    init_tracing(cli.debug);
33→
34→    tracing::debug!("Bivvy starting with args: {:?}", cli);
35→
36→    // Determine output mode
37→    let output_mode = if cli.quiet {
38→        OutputMode::Quiet
39→    } else if cli.verbose {
40→        OutputMode::Verbose
41→    } else {
42→        OutputMode::Normal
43→    };
44→
45→    // Handle --no-color
46→    if cli.no_color {
47→        std::env::set_var("NO_COLOR", "1");
48→    }
49→
50→    // Determine project root
51→    let project_root = cli
52→        .project
53→        .as_ref()
54→        .cloned()
55→        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
56→
57→    // Check if non-interactive (CI mode or explicit flag)
58→    let is_interactive = match &cli.command {
59→        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
60→        _ => !is_ci(),
61→    };
62→
63→    // Create UI
64→    let mut ui = create_ui(is_interactive, output_mode);
65→
66→    // Dispatch command
67→    let dispatcher = CommandDispatcher::new(project_root);
68→
69→    match dispatcher.dispatch(&cli, ui.as_mut()) {
70→        Ok(result) => ExitCode::from(result.exit_code as u8),
71→        Err(e) => {
72→            ui.error(&format!("Error: {}", e));
73→            ExitCode::from(1)
74→        }
75→    }
76→}
