 20→impl ConfigCommand {
 21→    /// Create a new config command.
 22→    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
 23→        Self {
 24→            project_root: project_root.to_path_buf(),
 25→            args,
 26→        }
 27→    }
 28→
 29→    /// Get the project root path.
 30→    pub fn project_root(&self) -> &Path {
 31→        &self.project_root
 32→    }
