  2→//!
  3→//! The `bivvy lint` command validates configuration files using the lint rule system.
  4→
  5→use std::path::{Path, PathBuf};
  6→
  7→use crate::cli::args::LintArgs;
  8→use crate::config::{load_merged_config, ConfigPaths};
  9→use crate::error::{BivvyError, Result};
 10→use crate::lint::{
 11→    CircularRequirementDepRule, Fix, FixEngine, HumanFormatter, InstallTemplateMissingRule,
 12→    JsonFormatter, LintDiagnostic, LintFormatter, RuleRegistry, SarifFormatter,
 13→    ServiceRequirementWithoutHintRule, Severity, TemplateInputsRule, UndefinedTemplateRule,
 14→    UnknownRequirementRule,
 15→};
 16→use crate::registry::Registry;
 17→use crate::requirements::registry::RequirementRegistry;
 18→use crate::ui::{OutputMode, UserInterface};
 19→
