/// Known top-level field names for BivvyConfig.
///
/// Used by [`check_unknown_fields`] to detect typos and invalid keys
/// that serde would otherwise silently ignore due to `#[serde(default)]`.
const KNOWN_CONFIG_FIELDS: &[&str] = &[
    "app_name",
    "settings",
    "template_sources",
    "steps",
    "workflows",
    "secrets",
    "extends",
    "requirements",
    "vars",
];

/// Reject unrecognized top-level keys in a raw YAML config value.
///
/// Without this check, `#[serde(default)]` on `BivvyConfig` silently
/// ignores unknown fields (e.g. typos like `stps` instead of `steps`),
/// causing the application to fall back to default config with no warning.
fn check_unknown_fields(value: &serde_yaml::Value, source_path: &Path) -> Result<()> {
    if let serde_yaml::Value::Mapping(map) = value {
        let unknown: Vec<String> = map
            .keys()
            .filter_map(|k| k.as_str())
            .filter(|k| !KNOWN_CONFIG_FIELDS.contains(k))
            .map(|k| format!("`{}`", k))
            .collect();

        if !unknown.is_empty() {
            let known = KNOWN_CONFIG_FIELDS
                .iter()
                .map(|f| format!("`{}`", f))
                .collect::<Vec<_>>()
                .join(", ");
            return Err(BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: format!(
                    "unknown field{} {}; expected one of: {}",
                    if unknown.len() > 1 { "s" } else { "" },
                    unknown.join(", "),
                    known,
                ),
            });
        }
    }
    Ok(())
}

/// Parse YAML content into BivvyConfig.
///
/// Rejects configs containing unrecognized top-level fields so that
/// typos are caught instead of silently falling back to defaults.
///
/// # Arguments
///
/// * `content` - The YAML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    let value: serde_yaml::Value =
        serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: e.to_string(),
        })?;

    check_unknown_fields(&value, source_path)?;

    serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

